    "n2_choices": [text(0, "A", role=True), text(1, "B", role=True), call(0, 0, "blocked_exfil", '{"to":"CANARY-4"}', role=False), call(0, 1, "read_file", "{}"), fin(1, "stop"), fin(0)],
