        row("error_mid_hold", &["\"terminal\""], &[], &["\"terminal\""], &[], false),
        row("json_body", &[], &["data:", "blocked_json"], &[], &["data:", "blocked_json"], false),
        row("lax_line", &["\"ok\""], &[], &["\"ok\""], &[], false),
