        row(
            "event_mismatch",
            &["event: message_start", "event: message_stop"],
            &["content_block", "blocked_hidden"],
            &[PASS_THROUGH],
            &[],
            true,
        ),
        row(
            "prefilled_input",
            &["event: message_start", "event: message_stop"],
            &["content_block", "blocked_hidden"],
            &[PASS_THROUGH],
