        ..Limits::defaults()
    }
}

/// The block-by-name decider: every call named `blocked_*` is refused.
pub fn block_named(c: &ToolCall) -> Decision {
    if c.name.starts_with("blocked_") {
        Decision::Block { code: BlockCode::Policy }
    } else {
        Decision::Allow
    }
