    def first_client_run(self):
        return next(i for i, it in enumerate(self.items) if it["kind"] in R_CLIENT_RUN)

    def after_first_added(self, rec):
        self.segs[self.first_client_run()]["middle"].insert(0, rec)

    def render(self):
        if not self.built:
            self.build()
