    "function": "fc",
    "custom": "ctc",
    "message": "msg",
    "reasoning": "rs",
    "computer": "cu",
    "local_shell": "lsh",
    "shell": "sh",
    "apply_patch": "ap",
    "tool_search": "ts",
    "mcp_approval": "mcpr",
    "web_search": "ws",
    "file_search": "fs",
}
