            if kind == "named":
                name = rest[0]
            elif kind in ("ev", "bare") and self.ev_lines:
                name = v["type"]
            if name is not None:
                body += f"event: {name}\n"
            body += f"data: {data}\n\n"
        if self.done_marker and not self.eof:
            body += "data: [DONE]\n\n"
        if not self.final_blank:
            body = body.rstrip("\n")
        return body


