fn responses_every_split_point_gives_the_same_output() {
    let mut covered = 0;
    std::thread::scope(|scope| {
        for rel in RESPONSES_SETS {
            for (name, bytes) in files(rel) {
                if bytes.len() > 6144 {
                    continue;
