                covered += 1;
                scope.spawn(move || {
                    let whole = drive(Format::OpenAiResponses, limits(OnFailure::Block), &[&bytes], &block_named).out;
                    for i in 0..=bytes.len() {
                        let split = drive(Format::OpenAiResponses, limits(OnFailure::Block), &[&bytes[..i], &bytes[i..]], &block_named).out;
